/* KIT vanilla — notice: inline status message with optional dismiss. */
.kit-notice {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: var(--kit-space-base, 12px) calc(var(--kit-space-base, 12px) * 1.25);
  border: 1px solid var(--border);
  border-radius: var(--radius-control, 8px);
  background: var(--plane-1, var(--muted));
  color: var(--foreground);
  font-size: var(--kit-body-size, 15px);
  line-height: var(--kit-leading, 1.5);
  max-width: var(--kit-reading-measure, 64ch);
}
.kit-notice::before {
  content: "";
  flex: none;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  margin-top: 7px;
  background: var(--muted-foreground);
}
.kit-notice[data-tone="positive"] { border-color: color-mix(in oklab, var(--positive) 40%, var(--border)); }
.kit-notice[data-tone="positive"]::before { background: var(--positive); }
.kit-notice[data-tone="destructive"] { border-color: color-mix(in oklab, var(--destructive) 40%, var(--border)); }
.kit-notice[data-tone="destructive"]::before { background: var(--destructive); }
.kit-notice > div { flex: 1; }
.kit-notice strong { display: block; font-weight: 700; }
.kit-notice [data-kit-dismiss] {
  appearance: none;
  border: none;
  background: none;
  color: var(--muted-foreground);
  font: inherit;
  font-size: var(--kit-compact-size, 12px);
  font-weight: 600;
  cursor: pointer;
  min-height: var(--kit-control-height, 44px);
  margin: calc(var(--kit-space-base, 12px) * -1) 0;
  padding: 0 8px;
}
.kit-notice [data-kit-dismiss]:hover { color: var(--foreground); }
.kit-notice [data-kit-dismiss]:focus-visible { outline: 2px solid var(--ring); outline-offset: 2px; }

/* KIT vanilla — notice behavior: dismiss removes the notice. */
(function () {
  document.addEventListener("click", function (event) {
    var dismiss = event.target.closest(".kit-notice [data-kit-dismiss]")
    if (dismiss) {
      var notice = dismiss.closest(".kit-notice")
      if (notice) notice.remove()
    }
  })
})();
